<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$title='Airtime';$u=current_user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)post('amount',0);$phone=trim((string)post('phone'));$network=trim((string)post('network'));$bal=(float)$u['balance'];if($amount<=0||$amount>$bal||$phone===''){flash('danger','Check the phone number and available balance.');}else{db()->beginTransaction();try{dbq('UPDATE users SET balance=balance-? WHERE id=?',[$amount,user_id()]);dbq('INSERT INTO bills(user_id,amount,type,network,phone,plan,trx,status,charge,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,0,NOW(),NOW())',[user_id(),$amount,'airtime',$network,$phone,'',trx()]);db()->commit();flash('success','Airtime transaction recorded successfully.');redirect('index.php?page=airtime');}catch(Throwable $e){db()->rollBack();flash('danger','Transaction could not be completed.');}}}require __DIR__.'/includes/header.php';?><div class="card"><h1>Buy Airtime</h1><p class="muted">Available balance: ₦<?=money($u['balance']??0)?></p><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Network</label><select name="network"><option>MTN</option><option>GLO</option><option>Airtel</option><option>9mobile</option></select></div><div class="field"><label>Phone number</label><input name="phone" required></div><div class="field"><label>Amount</label><input type="number" name="amount" step="0.01" min="1" required></div></div><br><button class="btn">Buy airtime</button></form></div><?php require __DIR__.'/includes/footer.php';?>
